"""Erstellt und versendet KPI-Auswertungen fuer digitale Preiscluster.

Das Modul fragt die Benchmark-Daten fuer einen Monat ab, exportiert sie nach
Excel und versendet den Export ueber Microsoft Graph an den definierten
Empfaengerkreis.
"""

import logging
import os
from datetime import datetime
from pathlib import Path

import pandas as pd

from ..constants import (
    CC_RECIPTENTS_KPI,
    KPI_PATH_DIGI_CLUSTER,
    RECIPTENTS_KPI,
)
from ..db.db_service import execute_dataframe_query, get_query_text
from ..messaging.ms_graph_mailer import mailer_from_encrypted_env
from ..utils.excel_utils import export_dataframe_to_excel

logger = logging.getLogger(__name__)


def digital_price_cluster(jahr: int, monat: int) -> pd.DataFrame:
    """Erstellt, exportiert und versendet den Digital-Basis-Benchmark.

    Die Daten werden ueber die Abfrage EXPORT_DIGI_BASIS_CLUSTER geladen.
    Bei einem leeren Ergebnis erfolgt kein Export und kein Versand. Der
    Rueckgabewert dokumentiert den Verarbeitungsstatus fuer Aufrufer.

    Args:
        jahr: Kalenderjahr des auszuwertenden Monats.
        monat: Auszuwertender Monat von 1 bis 12.

    Returns:
        DataFrame mit Versandstatus, Ausfuehrungszeitpunkt und Ausfuehrungs-ID.
    """

    # Die Datenbankabfrage ist zentral gepflegt und erwartet Jahr und Monat.
    query = get_query_text("EXPORT_DIGI_BASIS_CLUSTER")

    params = (jahr, monat)
    df = execute_dataframe_query(query, params=params)

    if df.empty:
        logger.info("Keine Einträge gefunden.")
        now = datetime.now()
        return pd.DataFrame(
            [
                {
                    "status": "keine Einträge",
                    "execution_time": now,
                    "execution_id": int(now.timestamp()),
                }
            ]
        )

    # Der Exportordner und die Empfaenger werden zentral konfiguriert.
    export_dir = Path(KPI_PATH_DIGI_CLUSTER)

    output = f"{datetime.now().strftime('%Y-%m-%d_%H-%M-%S')}_Benchmark_Digital_Basis_{jahr}_{monat:02d}"

    export_file = export_dataframe_to_excel(
        df,
        export_dir / f"{output}.xlsx",
        sheet_name="Benchmark",
        max_column_width=50,
    )

    # Nur tatsaechlich erzeugte Dateien werden als Anhang uebergeben.
    attachments: list[str | Path] = (
        [export_file] if export_file.exists() else []
    )
    
    body = (
        f"<p>Hallo zusammen,</p>"
        f"<p>anbei der aktuelle Digital Basis Benchmark MS und OWL "
        f"für {jahr}-{monat:02d} Stand: {datetime.now().strftime('%d.%m.%Y')}.</p>"
        f"<p>Beste Grüße,<br>DOA-Team Münster</p>"
    )
    subject = f"Digital Basis Benchmark MS und OWL für {jahr}-{monat:02d} Stand: {datetime.now().strftime('%d.%m.%Y')}"
    
    
    sender = os.environ.get("NOTIFICATION_SENDER", "")
    recipients_raw = RECIPTENTS_KPI
    cc_recipients_raw = CC_RECIPTENTS_KPI
    recipients = [r.strip() for r in recipients_raw.split(",") if r.strip()]
    cc_recipients = [r.strip() for r in cc_recipients_raw.split(",") if r.strip()]

    # Der Mailer liest die Graph-Zugangsdaten erst beim Versand aus der Konfiguration.
    mailer = mailer_from_encrypted_env(
        sender=sender,
        default_recipients=recipients,
    )
    now = datetime.now()
    try:
        # Ein Versandfehler wird im Status zurueckgegeben, damit Aufrufer ihn auswerten koennen.
        mailer.send(
            subject=subject,
            body=body,
            body_type="HTML",
            attachments=attachments,
            cc=cc_recipients,
        )
        logger.info(
            f"E-Mail mit Benchmark-Daten erfolgreich versendet an: {', '.join(recipients)}"
        )
        export_status = "verschickt"
    except Exception as e:
        logger.error(
            f"E-Mail mit Benchmark-Daten konnte nicht versendet werden: {e}", exc_info=True
        )
        export_status = "nicht verschickt"
    return pd.DataFrame(
        [
            {
                "status": export_status,
                "execution_time": now,
                "execution_id": int(now.timestamp()),
            }
        ]
    )
    
